begin;

update public.legal_organisations set careers_url='https://littletonchambers.com/join/pupillage/',research_status='verified',research_checked_on=date '2026-10-15',next_review_on=date '2026-11-02',updated_at=now() where id='39e0a960-36e3-4207-8fea-2d4e75e07646';
update public.chambers set pupillage_overview='Littleton offers up to two fully funded 12-month pupillages each year, occasionally one, across employment, commercial and sports law. Pupillages beginning from October 2027 carry an £85,000 award, with up to £15,000 available as a drawdown during the Bar Practice Course year. Selection normally comprises application review, two interview rounds and a three-day assessed mini-pupillage.',mini_pupillage_overview='Littleton does not operate a separately advertised general mini-pupillage round. It offers an assessed mini-pupillage within pupillage selection, dedicated placements through Bridging the Bar and PASS, and access-focused unassessed placements for applicants from less advantaged backgrounds.',research_status='verified',research_checked_on=date '2026-10-15',next_review_on=date '2026-11-02',updated_at=now() where organisation_id='39e0a960-36e3-4207-8fea-2d4e75e07646';

update public.career_opportunities set public_summary='Widening-access Academy providing mentoring, skills development and an allocated mini-pupillage through participating organisations, including Littleton Chambers.',official_url='https://bridgingthebar.org/academy-applications/',application_url='https://bridgingthebar.org/academy-applications/',research_checked_on=date '2026-10-15',next_review_on=date '2026-11-06',updated_at=now() where id='aebb7e90-a88d-4807-9304-5957761fe053';
update public.career_opportunity_cycles set cycle_label='Bridging the Bar Academy 2027/28 — Littleton Partner Mini-Pupillage Route',duration_text='August 2027 to June 2028',programme_starts_on=date '2027-08-01',programme_ends_on=date '2028-06-30',study_stage_text='Bar Course student in 2027–28 or Bar Course graduate intending to apply for pupillage in 2028.',academic_criteria='Selection considers academic excellence and understanding of a career at the Bar.',eligibility_text='Applicants must be studying the Bar Course in 2027–28 or have completed it, intend to apply for pupillage in 2028, have attended a UK state school, not have attended Oxford or Cambridge as an undergraduate, meet the Academy’s financial-support criterion and be available in the United Kingdom for all programme activity.',programme_dates_text='The Academy runs from August 2027 to June 2028.',application_process_text='Apply through the official Bridging the Bar Academy application page.',programme_structure_text='The Academy provides mentoring, application and interview training, advocacy preparation, workshops and at least one mini-pupillage allocated through a participating organisation.',source_status_note=null,research_checked_on=date '2026-10-15',updated_at=now() where id='2858a2ca-10e2-4730-ba6f-1751b70f7604';

update public.career_opportunities set public_summary='Funded 12-month employment, commercial and sports-law pupillage at Littleton Chambers, beginning in October 2028.',research_checked_on=date '2026-10-15',next_review_on=date '2027-01-29',updated_at=now() where id='2d156912-685e-49d8-9cfc-94e676d75802';
update public.career_opportunity_cycles set cycle_label='Littleton Chambers Pupillage — October 2028',intake_year=2028,funding_text='£85,000 award, with up to £15,000 available as a drawdown during the Bar Practice Course year. Pupils retain second-six earnings and Littleton funds required external training.',date_precision='exact',assessments_text='Application review, first-round interview, three-day assessed mini-pupillage with an opinion-writing exercise, and final interview.',right_to_work_text=null,research_checked_on=date '2026-10-15',updated_at=now() where id='4448fa4b-3c8b-4120-a47e-c66eb9e1868e';

update public.career_opportunities set public_name='Littleton Access-Focused Unassessed Mini-Pupillage',official_name='Littleton Access-Focused Unassessed Mini-Pupillage',public_summary='Continuously available access route through which Littleton considers requests for information and unassessed mini-pupillages from applicants from less advantaged backgrounds.',research_checked_on=date '2026-10-15',next_review_on=date '2027-01-15',updated_at=now() where id='6af9aa3a-858d-42b8-a669-73e66731b294';
update public.career_opportunity_cycles set cycle_label='Littleton Access-Focused Unassessed Mini-Pupillage',application_model='always_available',source_status='open',date_precision='text_only',duration_text='Arranged individually',expenses_text=null,assessments_text='The placement is unassessed.',academic_criteria=null,right_to_work_text=null,source_status_note=null,programme_dates_text='Placements are arranged individually throughout the year.',application_dates_text='Requests may be made throughout the year.',application_process_text='Contact Littleton Chambers with a concise request explaining your background, interest and the experience sought.',additional_details_text='Littleton considers suitable requests according to available capacity.',research_checked_on=date '2026-10-15',updated_at=now() where id='e26cf85c-8baa-4224-8572-95ce9f08643f';

update public.career_opportunities set public_summary='Continuously available sports-law work-experience and mentoring initiative offering three to four places each year for transitioning athletes and applicants from underrepresented socioeconomic backgrounds.',official_url='https://littletonchambers.com/about/social-responsibility/',application_url='https://littletonchambers.com/about/social-responsibility/',research_checked_on=date '2026-10-15',next_review_on=date '2027-01-15',updated_at=now() where id='a0c2f67d-9aeb-464d-b716-58835f63d340';
update public.career_opportunity_cycles set cycle_label='Littleton Inspire Sports Law Initiative',application_model='always_available',source_status='open',date_precision='text_only',duration_text='Work experience with continuing mentoring',expenses_text=null,assessments_text='Applications are reviewed from a one-page covering letter and two-page CV.',academic_criteria=null,right_to_work_text=null,source_status_note=null,programme_dates_text='Littleton offers three to four places each calendar year, arranged individually.',application_dates_text='Applications may be submitted throughout the year.',official_url='https://littletonchambers.com/about/social-responsibility/',application_url='https://littletonchambers.com/about/social-responsibility/',research_checked_on=date '2026-10-15',updated_at=now() where id='9a837c31-a91d-4ae4-9227-f215b71bb9c8';

insert into public.career_opportunities (organisation_id,opportunity_type_id,slug,official_name,public_name,public_summary,delivery_mode,official_url,application_url,active,published,research_checked_on,next_review_on)
select '39e0a960-36e3-4207-8fea-2d4e75e07646','06f22221-7e57-4379-b2a1-fcbec5d4f4bb','littleton-10000-black-interns-bar-2027','10,000 Black Interns — The Bar 2027 — Littleton Chambers Partner','10,000 Black Interns — The Bar 2027 — Littleton Chambers Partner','Paid six-week Bar internship programme for eligible Black students and recent graduates. Littleton helped establish the Bar workstream and publishes its continuing participation.','hybrid','https://10000internsfoundation.com/students-graduates/10000-black-interns/','https://10000internsfoundation.com/students-graduates/10000-black-interns/',true,true,date '2026-10-15',date '2026-11-02'
where not exists (select 1 from public.career_opportunities where organisation_id='39e0a960-36e3-4207-8fea-2d4e75e07646' and slug='littleton-10000-black-interns-bar-2027');

insert into public.career_opportunity_cycles (opportunity_id,cycle_key,cycle_label,application_year,programme_year,intake_year,application_model,closes_on,closes_timezone,programme_starts_on,programme_ends_on,programme_dates_text,application_dates_text,date_precision,duration_text,funding_text,source_status,study_stage_text,eligibility_text,right_to_work_text,official_url,application_url,active,research_checked_on,application_process_text,programme_structure_text,assessments_text,progression_route_text)
select o.id,'littleton-10000-black-interns-bar-2027','10,000 Black Interns — The Bar 2027 — Littleton Chambers Partner',2026,2027,2027,'fixed_deadline',date '2026-11-01','Europe/London',date '2027-06-01',date '2027-09-30','Six-week internships take place between June and September 2027, with dates agreed through the programme.','Applications for the Summer 2027 programme close on 1 November 2026.','exact','Six weeks','Paid internship at no less than the applicable real Living Wage.','open','UK undergraduate or postgraduate student, confirmed university entrant on a gap year, or recent UK-university graduate from 2024 or later.','Applicants must be aged 18 or over, be Black African, Black Caribbean, Black British or of mixed Black heritage, meet the programme’s UK study or recent-graduate criteria, and not previously have secured a 10,000 Black Interns placement.','Applicants must already have unrestricted permission to work full-time in the United Kingdom when applying.','https://10000internsfoundation.com/students-graduates/10000-black-interns/','https://10000internsfoundation.com/students-graduates/10000-black-interns/',true,date '2026-10-15','Apply through the 10,000 Interns Foundation and select The Bar workstream. Candidates may choose a region but cannot select an individual chambers.','The Bar workstream rotates interns across chambers and other Bar organisations. Littleton helped establish the Bar workstream and publishes its continuing participation.','The programme and participating hosts manage application review and selection.','No automatic progression to pupillage.'
from public.career_opportunities o where o.organisation_id='39e0a960-36e3-4207-8fea-2d4e75e07646' and o.slug='littleton-10000-black-interns-bar-2027'
and not exists (select 1 from public.career_opportunity_cycles c where c.opportunity_id=o.id);

